import { Component, ComponentInterface, Element, Event, EventEmitter, h, Host, Prop } from '@stencil/core';
import accept from 'attr-accept';
import { filter, fromEvent, Observable, Subject, takeUntil } from 'rxjs';
import { AcceptedFile, FilesSelectedEventDetails, FormDataEvent, RejectedFile } from '../../types';

@Component({
  tag: 'groupui-upload-dropzone',
  styleUrl: 'upload-dropzone.scss',
  shadow: true,
})
export class UploadDropzone implements ComponentInterface {
  /**
   * disables the component
   */
  @Prop({ mutable: true, reflect: true }) readonly disabled: boolean = false;

  /**
   * name of the upload dropzone element to support forms
   */
  @Prop({ reflect: true }) readonly name: string = 'files';

  /**
   * allows multiple file selection
   */
  @Prop({ reflect: true }) readonly multiple: boolean = false;

  /**
   * defines the file types the dropzone should accept.
   * See https://www.w3schools.com/TAGS/att_input_accept.asp
   */
  @Prop({ reflect: true }) readonly accept: string;

  /**
   * event emitted when files are selected, the event detail contains the file list of the selected files
   * Format: { acceptedFiles: FileList; rejectedFiles: FileList }
   */
  @Event({ bubbles: false }) groupuiFilesSelected: EventEmitter<FilesSelectedEventDetails>;

  @Element() host: HTMLElement;

  private destroy: Subject<void>;
  private selectedFiles: File[];

  private clickListener: Observable<Event>;
  private keyboardListener: Observable<KeyboardEvent>;
  private filesSelectedListener: Observable<Event>;
  private dragEnterListener: Observable<Event>;
  private dragLeaveListener: Observable<Event>;
  private dropListener: Observable<DragEvent>;
  private formsListener: Observable<Event>;

  connectedCallback() {
    this.destroy = new Subject();
    this.cancelDefaultDragBehavior();

    if (this.clickListener) this.attachClickHandling();
    if (this.keyboardListener) this.attachKeyboardHandling();
    if (this.filesSelectedListener) this.attachFilesSelectedHandling();
    if (this.dragEnterListener) this.attachDragEnterHandling();
    if (this.dragLeaveListener) this.attachDragLeaveHandling();
    if (this.dropListener) this.attachDropHandling();
    if (this.formsListener) this.attachFormsHandling();
  }

  componentDidLoad() {
    this.clickListener = fromEvent(this.dragZone(), 'click');
    this.keyboardListener = fromEvent<KeyboardEvent>(this.host, 'keydown').pipe(
      filter((event) => event.code === 'Enter' || event.code === 'Space')
    );
    this.filesSelectedListener = fromEvent(this.fileInput(), 'change');
    this.dragEnterListener = fromEvent(this.dragZone(), 'dragenter');
    this.dragLeaveListener = fromEvent(this.dragZone(), 'dragleave');
    this.dropListener = fromEvent<DragEvent>(this.dragZone(), 'drop');

    if (this.form()) {
      this.formsListener = fromEvent(this.form(), 'formdata');
      this.attachFormsHandling();
    }

    this.attachClickHandling();
    this.attachKeyboardHandling();
    this.attachFilesSelectedHandling();
    this.attachDragEnterHandling();
    this.attachDragLeaveHandling();
    this.attachDropHandling();
  }

  private attachClickHandling() {
    this.clickListener.pipe(takeUntil(this.destroy)).subscribe(() => {
      if (this.disabled) return;
      this.fileInput().click();
    });
  }

  private attachKeyboardHandling() {
    this.keyboardListener.pipe(takeUntil(this.destroy)).subscribe((event) => {
      this.fileInput().click();
      event.preventDefault();
    });
  }

  private attachFilesSelectedHandling() {
    this.filesSelectedListener.pipe(takeUntil(this.destroy)).subscribe((event: Event) => {
      const files = Array.from((event.target as HTMLInputElement).files);
      this.selectedFiles = files;
      this.groupuiFilesSelected.emit({ acceptedFiles: files, rejectedFiles: [] });
    });
  }

  private attachDragEnterHandling() {
    this.dragEnterListener.pipe(takeUntil(this.destroy)).subscribe(() => {
      this.dragZone().classList.add('drag-over');
    });
  }

  private attachDragLeaveHandling() {
    this.dragLeaveListener.pipe(takeUntil(this.destroy)).subscribe(() => {
      this.dragZone().classList.remove('drag-over');
    });
  }

  private attachDropHandling() {
    this.dropListener.pipe(takeUntil(this.destroy)).subscribe((event: DragEvent) => {
      if (this.disabled) return;

      const allFiles = Array.from(event.dataTransfer.files);
      const acceptedFiles: AcceptedFile[] = [];
      const rejectedFiles: RejectedFile[] = [];

      allFiles.forEach((file, i) => {
        if (!accept(file, this.accept)) {
          rejectedFiles.push({ file: file, reason: 'wrong format' });
          return;
        }
        if (!this.multiple && i > 0) {
          rejectedFiles.push({ file: file, reason: 'surplus file' });
          return;
        }
        acceptedFiles.push(file);
      });

      this.selectedFiles = acceptedFiles;
      this.groupuiFilesSelected.emit({ acceptedFiles, rejectedFiles });
      this.dragZone().classList.remove('drag-over');
    });
  }

  private attachFormsHandling() {
    this.formsListener.pipe(takeUntil(this.destroy)).subscribe((event: FormDataEvent) => {
      if (this.disabled) return;
      if (this.name === undefined) return;
      if (this.selectedFiles) {
        Array.from(this.selectedFiles).forEach((file) => {
          event.formData.append(this.name, file);
        });
      }
    });
  }

  private cancelDefaultDragBehavior() {
    fromEvent(window, 'dragover')
      .pipe(takeUntil(this.destroy))
      .subscribe((e) => e.preventDefault());

    fromEvent(window, 'drop')
      .pipe(takeUntil(this.destroy))
      .subscribe((e) => e.preventDefault());
  }

  disconnectedCallback() {
    this.destroy.next();
    this.destroy.complete();
  }

  private dragZone(): HTMLElement {
    return this.host.shadowRoot.querySelector('#drag-zone');
  }

  private fileInput(): HTMLInputElement {
    return this.host.shadowRoot.querySelector('input[type="file"]');
  }

  private form(): HTMLFormElement | null {
    return this.host.closest('form');
  }

  render() {
    return (
      <Host tabIndex={this.disabled ? -1 : 0}>
        <slot name="label"></slot>
        <div id="drag-zone">
          <div id="action">
            <groupui-icon name={'upload-24'}></groupui-icon>
            <groupui-headline heading={'h6'}>
              <slot />
            </groupui-headline>
          </div>
          <slot name="description"></slot>
        </div>
        <input type="file" disabled={this.disabled} name={this.name} multiple={this.multiple} accept={this.accept} />
      </Host>
    );
  }
}
